CREATE TABLE IF NOT EXISTS registrations (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, type ENUM('etudiant','enseignant') NOT NULL, full_name VARCHAR(180) NOT NULL, email VARCHAR(254) NOT NULL, phone VARCHAR(50) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_type_created (type,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
